<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class LearningPortalService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function course(mixed $id):array {$c=$this->row('learning_courses','course_id',$id);$this->access->requireSite($c['site_id']);return $c;}
    private function assignment(string $id):array {$a=$this->row('learning_assignments','assignment_id',$id);if((string)$a['employee_id']!==$this->employee())throw HttpException::notFound();$this->course($a['course_id']);if($this->row('employees','employee_id',$a['employee_id'])['employment_status']!=='ACTIVE')throw HttpException::forbidden('An active employee is required.');return $a;}
    public function list(array $input,bool $self=false):array
    {
        $this->fields($input,$self?[]:['site_id']);$p=['company'=>$this->company()];if(!$self){$site=$this->access->requireSite($input['site_id']??null);$p['site']=$site['site_id'];}else $p['employee']=$this->employee();
        $rows=$this->db->fetchAll('SELECT c.* FROM learning_courses c WHERE c.company_id=:company'.($self?' AND EXISTS(SELECT 1 FROM learning_assignments a WHERE a.company_id=c.company_id AND a.course_id=c.course_id AND a.employee_id=:employee)':' AND c.site_id=:site').' ORDER BY course_id DESC LIMIT 200',$p);
        $out=[];foreach($rows as$c){if(!$this->access->allowed($c['site_id']))continue;$quiz=json_decode($c['quiz_json'],true,512,JSON_THROW_ON_ERROR);if($self)foreach($quiz as&$q)unset($q['correct']);unset($q);unset($c['quiz_json']);$c['quiz']=$quiz;$v=['company'=>$this->company(),'course'=>$c['course_id']];if($self)$v['employee']=$this->employee();$c['assignments']=$this->db->fetchAll('SELECT a.*,t.certificate_id,t.certificate_code,t.issued_at,t.expires_on,t.revoked_at,t.revocation_reason FROM learning_assignments a LEFT JOIN learning_certificates t ON t.company_id=a.company_id AND t.assignment_id=a.assignment_id WHERE a.company_id=:company AND a.course_id=:course'.($self?' AND a.employee_id=:employee':'').' ORDER BY assignment_id DESC LIMIT 500',$v);foreach($c['assignments']as&$a){$a['attempts']=$this->db->fetchAll('SELECT attempt_id,score_percent,passed,submitted_at FROM learning_attempts WHERE company_id=:company AND assignment_id=:assignment ORDER BY attempt_id',['company'=>$this->company(),'assignment'=>$a['assignment_id']]);$a['certificate_state']=$a['revoked_at']?'REVOKED':($a['certificate_id']?($a['expires_on']<gmdate('Y-m-d')?'EXPIRED':'CURRENT'):'NOT_ISSUED');}unset($a);$out[]=$c;}return $out;
    }
    public function create(array $input):array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','title','lesson','quiz','pass_percent','valid_days','max_attempts']);$site=$this->access->requireSite($input['site_id']??null);$quiz=$input['quiz']??null;
        if(!is_array($quiz)||!array_is_list($quiz)||count($quiz)<1||count($quiz)>20)throw HttpException::unprocessable('Use 1–20 quiz questions.');$normal=[];
        foreach($quiz as$q){if(!is_array($q))throw HttpException::unprocessable('Invalid quiz question.');$this->fields($q,['question','options','correct']);$options=$q['options']??null;if(!is_array($options)||!array_is_list($options)||count($options)<2||count($options)>6)throw HttpException::unprocessable('Use 2–6 answer choices.');$options=array_map(fn($v)=>$this->text($v,300),$options);if(count(array_unique($options))!==count($options))throw HttpException::unprocessable('Answer choices must differ.');$normal[]=['question'=>$this->text($q['question']??null,1000),'options'=>$options,'correct'=>$this->number($q['correct']??null,0,count($options)-1)];}
        $title=$this->text($input['title']??null,150);$lesson=$this->text($input['lesson']??null,30000);$pass=$this->number($input['pass_percent']??null,1,100);$days=$this->number($input['valid_days']??null,1,730);$max=$this->number($input['max_attempts']??null,1,10);$json=json_encode($normal,JSON_THROW_ON_ERROR);$hash=hash('sha256',json_encode([$title,$lesson,$normal,$pass,$days,$max],JSON_THROW_ON_ERROR));
        $this->db->execute('INSERT INTO learning_courses(company_id,site_id,title,lesson,quiz_json,pass_percent,valid_days,max_attempts,content_hash,created_by_user_id,created_at) VALUES(:company,:site,:title,:lesson,:quiz,:pass,:days,:max,:hash,:actor,:now)',['company'=>$this->company(),'site'=>$site['site_id'],'title'=>$title,'lesson'=>$lesson,'quiz'=>$json,'pass'=>$pass,'days'=>$days,'max'=>$max,'hash'=>$hash,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('learning_course');
    });}
    public function publish(string $id):array {return $this->atomic(function()use($id){$c=$this->course($id);if($c['state']!=='DRAFT')throw HttpException::conflict('Course is already published.');$this->db->execute("UPDATE learning_courses SET state='PUBLISHED',published_at=:now WHERE company_id=:company AND course_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('learning_course','published',$id);return ['published'=>true,'note'=>'Published editions are immutable; create a new course edition for changes.'];});}
    public function assign(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['employee_id','due_on']);$c=$this->course($id);$e=$this->row('employees','employee_id',$input['employee_id']??null);$due=$this->day($input['due_on']??null);if($c['state']!=='PUBLISHED'||$e['employment_status']!=='ACTIVE'||$due<gmdate('Y-m-d'))throw HttpException::unprocessable('Choose a published course, active employee and current/future deadline.');if($this->db->fetch('SELECT assignment_id FROM learning_assignments WHERE company_id=:company AND course_id=:course AND employee_id=:employee',['company'=>$this->company(),'course'=>$id,'employee'=>$e['employee_id']]))throw HttpException::conflict('Employee already has this course edition.');$this->db->execute('INSERT INTO learning_assignments(company_id,course_id,employee_id,due_on,assigned_by_user_id,assigned_at) VALUES(:company,:course,:employee,:due,:actor,:now)',['company'=>$this->company(),'course'=>$id,'employee'=>$e['employee_id'],'due'=>$due,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('learning_assignment');});}
    public function readLesson(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['content_hash','read']);$a=$this->assignment($id);$c=$this->course($a['course_id']);if(($input['read']??null)!==true||!is_string($input['content_hash']??null)||!hash_equals($c['content_hash'],$input['content_hash']))throw HttpException::conflict('Confirm the exact published lesson.');$this->db->execute('UPDATE learning_assignments SET read_at=COALESCE(read_at,:now) WHERE company_id=:company AND assignment_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('learning_assignment','lesson_acknowledged',$id);return ['read'=>true];});}
    public function submit(string $id,array $input):array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['operation_uuid','content_hash','answers']);$a=$this->assignment($id);$c=$this->course($a['course_id']);$uuid=$input['operation_uuid']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/Di',$uuid))throw HttpException::unprocessable('Use a stable operation UUID.');$hash=hash('sha256',json_encode([$id,$this->actor(),$input['content_hash']??null,$input['answers']??null],JSON_THROW_ON_ERROR));$prior=$this->db->fetch('SELECT * FROM learning_attempts WHERE company_id=:company AND operation_uuid=:uuid',['company'=>$this->company(),'uuid'=>$uuid]);if($prior){if(!hash_equals($prior['request_hash'],$hash))throw HttpException::conflict('Attempt retry payload changed.');return ['score_percent'=>(int)$prior['score_percent'],'passed'=>(bool)$prior['passed']];}
        if($a['state']!=='ASSIGNED'||!$a['read_at']||!is_string($input['content_hash']??null)||!hash_equals($c['content_hash'],$input['content_hash']))throw HttpException::conflict('Read the assigned lesson before an attempt; completed assignments cannot be retaken.');$quiz=json_decode($c['quiz_json'],true,512,JSON_THROW_ON_ERROR);$answers=$input['answers']??null;if(!is_array($answers)||!array_is_list($answers)||count($answers)!==count($quiz))throw HttpException::unprocessable('Answer every question.');$attempts=$this->db->fetch('SELECT COUNT(*) AS n FROM learning_attempts WHERE company_id=:company AND assignment_id=:id',['company'=>$this->company(),'id'=>$id]);if((int)$attempts['n']>=(int)$c['max_attempts'])throw HttpException::conflict('Attempt limit reached; request supervisor follow-up or a new course edition.');$correct=0;foreach($quiz as$i=>$q)if($this->number($answers[$i],0,count($q['options'])-1)===$q['correct'])$correct++;$score=(int)floor(100*$correct/count($quiz));$passed=$score>=(int)$c['pass_percent'];$now=gmdate('Y-m-d H:i:s');$this->db->execute('INSERT INTO learning_attempts(company_id,assignment_id,operation_uuid,request_hash,score_percent,passed,submitted_by_user_id,submitted_at) VALUES(:company,:assignment,:uuid,:hash,:score,:passed,:actor,:now)',['company'=>$this->company(),'assignment'=>$id,'uuid'=>$uuid,'hash'=>$hash,'score'=>$score,'passed'=>(int)$passed,'actor'=>$this->actor(),'now'=>$now]);if($passed){$this->db->execute("UPDATE learning_assignments SET state='PASSED' WHERE company_id=:company AND assignment_id=:id",['company'=>$this->company(),'id'=>$id]);$this->db->execute('INSERT INTO learning_certificates(company_id,assignment_id,certificate_code,issued_at,expires_on) VALUES(:company,:assignment,:code,:now,:expires)',['company'=>$this->company(),'assignment'=>$id,'code'=>uuid4(),'now'=>$now,'expires'=>gmdate('Y-m-d',time()+(int)$c['valid_days']*86400)]);}$this->audit->record('learning_attempt','submitted',$id,[],[],['score_percent'=>$score,'passed'=>$passed]);return ['score_percent'=>$score,'passed'=>$passed,'note'=>'Internal course completion only; not a statutory licence or verified deployment competency.'];
    });}
    public function revoke(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['reason']);$t=$this->row('learning_certificates','certificate_id',$id);$a=$this->row('learning_assignments','assignment_id',$t['assignment_id']);$this->course($a['course_id']);if($t['revoked_at'])throw HttpException::conflict('Certificate already revoked.');$this->db->execute('UPDATE learning_certificates SET revoked_at=:now,revocation_reason=:reason WHERE company_id=:company AND certificate_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'reason'=>$this->text($input['reason']??null,1000),'company'=>$this->company(),'id'=>$id]);$this->audit->record('learning_certificate','revoked',$id);return ['revoked'=>true];});}
}
